example.code:
#include <iostream>

void hitCopy(int health) { health -= 10; }
void hitRef(int& health) { health -= 10; }

int main()
{
    int h = 50;
    hitCopy(h);
    std::cout << "after copy: " << h << "\n";
    hitRef(h);
    std::cout << "after reference: " << h << "\n";
    return 0;
}

